security_disable_keys = {"validate_certs", "ssl", "tls_enabled", "enable_https_only", "secure_transfer", "require_secure_transfer", "https_only", "require_ssl", "ssl_mode"}

# Helper function to check if an expression contains an insecure protocol
contains_insecure_protocol(expr) {
    expr.ir_type == "String"
    regex.match("^(http|ftp|telnet|smtp)://", expr.value)
} else {
    expr.ir_type == "Sum"
    contains_insecure_protocol(expr.left) || contains_insecure_protocol(expr.right)
} else {
    expr.ir_type == "Hash"
    some key, value in expr.value
    contains_insecure_protocol(value)
} else {
    expr.ir_type == "Array"
    some element in expr.value
    contains_insecure_protocol(element)
} else {
    false
}

# Helper function to check if a value is a disable value for security settings
is_disable_value(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower_case := lower(value.value)
    lower_case == "no" || lower_case == "disabled" || lower_case == "none"
}

